        var group = app.MapGroup("/api/items").RequireAuthorization();

        group.MapGet("/", GetAllItems);
        group.MapGet("/{id:int}", GetItemById);
        group.MapPost("/", CreateItem);
        group.MapPut("/{id:int}", UpdateItem);
        group.MapDelete("/{id:int}", DeleteItem);

        return app;
    }

